// Corresponds with POST /api/bff/tables/{table}/records (the `CreateRecord` operationId).
func (c *ClientWithResponses) CreateRecordWithResponse(ctx context.Context, table string, body CreateRecordJSONRequestBody, reqEditors ...RequestEditorFn) (*CreateRecordResponse, error) {
	rsp, err := c.CreateRecord(ctx, table, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseCreateRecordResponse(rsp)
}

// ParseGetBootstrapResponse parses an HTTP response from a GetBootstrapWithResponse call
func ParseGetBootstrapResponse(rsp *http.Response) (*GetBootstrapResponse, error) {
	bodyBytes, err := io.ReadAll(rsp.Body)
	defer func() { _ = rsp.Body.Close() }()
	if err != nil {
		return nil, err
	}

	response := &GetBootstrapResponse{
		Body:         bodyBytes,
		HTTPResponse: rsp,
	}

	switch {
	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && rsp.StatusCode == 200:
		var dest Bootstrap
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.JSON200 = &dest

	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && rsp.StatusCode == 401:
		var dest SessionRequired
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.JSON401 = &dest

	}

	return response, nil
}

